actor TokenProvider {
    private var token: Token?
    private var refreshTask: Task<Token, Error>?
    private let api: AuthAPI

    init(api: AuthAPI) { self.api = api }

    func validToken() async throws -> Token {
        if let token, !token.isExpiringSoon { return token }
        return try await refresh()
    }

    func refresh() async throws -> Token {
        if let refreshTask { return try await refreshTask.value }   // join
        let task = Task { try await api.refresh(token?.refreshToken) }
        refreshTask = task
        defer { refreshTask = nil }
        let new = try await task.value
        token = new
        return new
    }
}
